<template><v-row justify="center" class="auth-layout"><v-col cols="12" sm="9" md="6" lg="5"><v-card class="auth-card pa-7"><div class="text-center mb-7"><v-avatar color="secondary" size="62" class="mb-3"><v-icon icon="mdi-car-wrench" size="34"/></v-avatar><h1 class="text-h4 font-weight-bold">Bienvenido</h1><p class="text-medium-emphasis mt-2">Accede al control de tu vehículo y servicios.</p></div><AppAlert :message="error" @clear="error=''"/><v-form v-model="valid" @submit.prevent="submit"><v-text-field v-model.trim="form.username" label="Usuario" prepend-inner-icon="mdi-account-outline" :rules="[v=>!!v||'El usuario es obligatorio']"/><v-text-field v-model="form.password" label="Contraseña" prepend-inner-icon="mdi-lock-outline" type="password" :rules="[v=>!!v||'La contraseña es obligatoria']"/><v-btn block size="large" color="primary" :loading="loading" type="submit" :disabled="!valid">Entrar al taller</v-btn></v-form><div class="d-flex justify-space-between mt-6"><router-link to="/registro">Crear cuenta</router-link><router-link to="/recuperar">Recuperar acceso</router-link></div></v-card></v-col></v-row></template>
<script setup>import { ref } from 'vue'; import { useRouter,useRoute } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import AppAlert from '../components/AppAlert.vue'; const form=ref({username:'',password:''}),valid=ref(false),loading=ref(false),error=ref(''),auth=useAuthStore(),router=useRouter(),route=useRoute(); async function submit(){loading.value=true;error.value='';try{await auth.login(form.value);router.push(route.query.redirect||'/perfil')}catch(e){error.value=e.response?.data?.detail||'No fue posible iniciar sesión'}finally{loading.value=false}}</script>
